def generate(rng):
    H=rng.randint(12,24); W=rng.randint(10,22)
    bg=6; obj=5; mark=8
    g=[[bg]*W for _ in range(H)]
    # solid rectangle
    rh=rng.randint(2,max(2,H//4)); rw=rng.randint(2,max(2,W//3))
    r0=rng.randint(2,H-rh-2); c0=rng.randint(2,W-rw-2)
    for r in range(r0,r0+rh):
        for c in range(c0,c0+rw): g[r][c]=obj
    # aligned markers outside, one or both directions
    markers=[]
    if rng.random()<.8:
        c=rng.randrange(c0,c0+rw); r=rng.randrange(0,r0); markers.append((r,c))
    if rng.random()<.8:
        c=rng.randrange(c0,c0+rw); r=rng.randrange(r0+rh,H); markers.append((r,c))
    if rng.random()<.8:
        r=rng.randrange(r0,r0+rh); c=rng.randrange(0,c0); markers.append((r,c))
    if rng.random()<.8:
        r=rng.randrange(r0,r0+rh); c=rng.randrange(c0+rw,W); markers.append((r,c))
    # distractors not sharing row/col with rectangle
    for _ in range(rng.randint(1,4)):
        for tries in range(30):
            r=rng.randrange(H); c=rng.randrange(W)
            if g[r][c]==bg and r not in range(r0,r0+rh) and c not in range(c0,c0+rw):
                markers.append((r,c)); break
    for r,c in markers: g[r][c]=mark
    return g"}

